# ============================================================
# OUTILS OPENAI
# ============================================================

def call_openai(messages, temperature=0.2):
    response = client.chat.completions.create(
        model=MODEL_NAME,
        messages=messages,
        temperature=temperature,
    )
    return response.choices[0].message.content

# ============================================================
# SAUVEGARDE / REPRISE
# ============================================================

def save_session(code, history, student_state, image_visible):
    if redis_client is None:
        return False, (
            "Le stockage persistant n'est pas configuré. "
            "Ajoute UPSTASH_REDIS_REST_URL et UPSTASH_REDIS_REST_TOKEN "
            "dans les Secrets Streamlit."
        )

    data = {
        "history": history,
        "student_state": student_state,
        "image_visible": image_visible,
    }

    try:
        redis_client.set(
            f"dujardin:{code}",
            json.dumps(data, ensure_ascii=False),
        )
        return True, None
    except Exception as exc:
        return False, (
            "La sauvegarde persistante est momentanément indisponible. "
            "Vérifie les paramètres Upstash dans les Secrets Streamlit. "
            f"Détail technique : {exc.__class__.__name__}"
        )


def autosave_current_session():
    code = st.session_state.get("save_code")
    if not code:
        return

    save_session(
        code,
        st.session_state.history,
        st.session_state.student_state,
        st.session_state.image_visible,
    )


def load_session(code):
    if redis_client is None:
        return None

    try:
        raw = redis_client.get(f"dujardin:{code}")
    except Exception:
        return None

    if raw is None:
        return None

    if isinstance(raw, bytes):
        raw = raw.decode("utf-8")

    try:
        return json.loads(raw)
    except Exception:
        return None


def generate_report_code():
    return uuid.uuid4().hex[:6].upper()


def save_final_report(report_code, student_state, history, assessment, report_text, report_pdf):
    if redis_client is None:
        return False, "Le stockage du rapport n'est pas configuré."

    payload = {
        "student_state": student_state,
        "history": history,
        "assessment": assessment,
        "report_text": report_text,
        "report_pdf_b64": base64.b64encode(report_pdf).decode("ascii") if report_pdf else None,
    }

    try:
        redis_client.set(
            f"dujardin_report:{report_code}",
            json.dumps(payload, ensure_ascii=False),
        )
        return True, None
    except Exception as exc:
        return False, f"Le rapport n'a pas pu être enregistré ({exc.__class__.__name__})."

# ============================================================
# DIALOGUE DU RAPPORT
# ============================================================

def is_technical_command(content):
    upper = (content or "").strip().upper()
    return (
        upper == "SAUVEGARDE"
        or upper == "RECOMMENCER"
        or upper.startswith("REPRISE ")
    )


def get_consultation_dialogue(history):
    dialogue = []
    consultation_started = False

    for msg in history:
        if not isinstance(msg, dict):
            continue

        role = msg.get("role")
        content = (msg.get("content") or "").strip()

        if not content or is_technical_command(content):
            continue

        if role == "assistant" and content == INTRO_MESSAGE:
            consultation_started = True

        if consultation_started:
            dialogue.append({
                "role": role,
                "content": content,
            })

    return dialogue


def build_dialogue_text(history):
    dialogue = get_consultation_dialogue(history)

    if not dialogue:
        return "Aucun dialogue de téléconsultation."

    lines = []

    for msg in dialogue:
        speaker = "Élève (médecin)" if msg["role"] == "user" else "M. Dujardin"
        lines.append(f"{speaker} : {msg['content']}")

    return "\n".join(lines)


def build_student_only_text(history):
    """Source principale pour noter : uniquement les productions de l'élève."""
    dialogue = get_consultation_dialogue(history)

    student_messages = [
        msg["content"]
        for msg in dialogue
        if msg.get("role") == "user"
    ]

    if not student_messages:
        return "Aucune production de l'élève."

    return "\n".join(
        f"Réponse élève {index} : {content}"
        for index, content in enumerate(student_messages, start=1)
    )

# ============================================================
# ÉVALUATION
# ============================================================

def normalize_assessment(data, student_state=None):
    result = {
        "competences": [],
        "appreciation": str(data.get("appreciation", "")).strip(),
    }

    student_state = student_state or {}
    returned = data.get("competences", [])
    by_name = {}

    vocab_used = student_state.get("vocab_help_used", []) or []
    docs_used = student_state.get("help_docs_used", []) or []

    doc_ids = {
        item.get("id") if isinstance(item, dict) else item
        for item in docs_used
    }

    def clamp(value, default=1):
        try:
            value = int(value)
        except Exception:
            value = default
        return min(4, max(1, value))

    def composite_cap(name, subparts, base_autonomy):
        values = [
            clamp(part.get("autonomie", base_autonomy), base_autonomy)
            for part in subparts
            if isinstance(part, dict)
        ]

        cap = base_autonomy

        if name == "Expliquer les manifestations de la réaction inflammatoire":
            low = sum(v <= 2 for v in values)
            if low >= 2:
                cap = min(cap, 2)
            if {"INFLAMMATION_P1", "INFLAMMATION_P2"} & doc_ids:
                cap = min(cap, 2)

        elif name == "Expliquer le rôle des cellules sentinelles et des médiateurs chimiques":
            if any(v <= 2 for v in values):
                cap = min(cap, 2)
            if "INFLAMMATION_P1" in doc_ids:
                cap = min(cap, 2)

        elif name == "Expliquer le rôle des leucocytes dans la défense de l'organisme":
            # La compétence comporte le rôle général ET le recrutement vers la zone lésée.
            if any(v <= 2 for v in values):
                cap = min(cap, 2)
            if "INFLAMMATION_P2" in doc_ids:
                cap = min(cap, 2)

        elif name == "Expliquer les étapes de la phagocytose":
            low = sum(v <= 2 for v in values)
            if low >= 2:
                cap = min(cap, 2)
            if {"PHAGO_ETAPES", "PHAGO_ANNOTATION"} & doc_ids:
                cap = min(cap, 2)

        elif name == "Comprendre et utiliser le vocabulaire scientifique dans une communication écrite adaptée":
            if len(vocab_used) >= 3:
                cap = min(cap, 2)
            elif len(vocab_used) >= 1:
                cap = min(cap, 3)

        return cap

    for item in returned:
        if not isinstance(item, dict):
            continue

        name = str(item.get("nom", "")).strip()
        content_level = clamp(item.get("niveau_contenu", item.get("niveau", 1)))
        autonomy_level = clamp(item.get("autonomie", content_level), content_level)
        subparts = item.get("sous_parties", [])
        if not isinstance(subparts, list):
            subparts = []

        autonomy_level = composite_cap(
            name,
            subparts,
            autonomy_level,
        )

        # Règle déterministe : le niveau final ne dépasse jamais l'autonomie.
        level = min(content_level, autonomy_level)

        justification = str(item.get("justification", "")).strip()

        if autonomy_level <= 2 and justification:
            lower = justification.lower()
            if not any(word in lower for word in ("aide", "guid", "relance", "étay", "document")):
                justification += (
                    " L'élève a eu besoin d'un étayage important, "
                    "ce qui limite le niveau d'autonomie."
                )

        by_name[name] = {
            "nom": name,
            "niveau": level,
            "niveau_contenu": content_level,
            "autonomie": autonomy_level,
            "sous_parties": subparts,
            "justification": justification,
        }

    for expected_name in COMPETENCY_NAMES:
        item = by_name.get(expected_name)

        if item is None:
            item = {
                "nom": expected_name,
                "niveau": 1,
                "niveau_contenu": 1,
                "autonomie": 1,
                "sous_parties": [],
                "justification": "Évaluation automatique indisponible pour cette compétence.",
            }

        result["competences"].append(item)

    if not result["appreciation"]:
        result["appreciation"] = (
            "Le bilan met en évidence les acquis et les points à consolider au cours de la téléconsultation."
        )

    return result

def generate_assessment(history, student_state):
    dialogue_text = build_dialogue_text(history)
    student_only_text = build_student_only_text(history)

    vocab_used = (student_state or {}).get("vocab_help_used", []) or []
    docs_used = (student_state or {}).get("help_docs_used", []) or []

    aid_trace = (
        "TRACE DES AIDES OUTILS :\n"
        f"- Mots consultés dans le lexique : {', '.join(vocab_used) if vocab_used else 'aucun'}\n"
        f"- Documents de classe consultés : "
        f"{', '.join(item.get('title', item.get('id', '')) if isinstance(item, dict) else str(item) for item in docs_used) if docs_used else 'aucun'}\n"
    )

    raw = call_openai(
        [
            {"role": "system", "content": ASSESSMENT_SYSTEM_PROMPT},
            {
                "role": "user",
                "content": (
                    "SOURCE PRINCIPALE POUR NOTER : PRODUCTIONS DE L'ÉLÈVE UNIQUEMENT.\n"
                    "Attribue les acquis uniquement à partir de cette partie :\n\n"
                    f"{student_only_text}\n\n"
                    "CONTEXTE SECONDAIRE : DIALOGUE COMPLET.\n"
                    "Utilise cette partie pour mesurer précisément les relances, indices et le guidage de M. Dujardin.\n"
                    "Pour chaque compétence, repère si l'élève répond spontanément, après une petite relance, "
                    "après plusieurs indices, ou grâce à un guidage étape par étape.\n"
                    "N'attribue jamais à l'élève une information formulée uniquement par M. Dujardin.\n"
                    "IMPORTANT : si une compétence est reconstruite pas à pas par plusieurs questions de M. Dujardin, "
                    "l'autonomie vaut 2 au maximum, même si les réponses finales sont toutes correctes.\n"
                    "Une consultation d'un document de classe est une aide importante : elle ne permet pas un niveau d'autonomie supérieur à 2 "
                    "pour la compétence concernée.\n"
                    "Une ou deux consultations ponctuelles du lexique peuvent rester compatibles avec le niveau 3 de vocabulaire ; "
                    "plusieurs consultations indiquent une fragilité.\n\n"
                    f"{aid_trace}\n"
                    f"{dialogue_text}"
                ),
            },
        ],
        temperature=0.0,
    )

    cleaned = raw.strip()

    if cleaned.startswith("```"):
        cleaned = cleaned.strip("`")
        if cleaned.lower().startswith("json"):
            cleaned = cleaned[4:].strip()

    try:
        data = json.loads(cleaned)
    except Exception:
        raise RuntimeError(
            "L'évaluation automatique n'a pas renvoyé un JSON valide. "
            "Relance la génération du bilan."
        )

    return normalize_assessment(data, student_state)

# ============================================================
# RAPPORT TEXTE
# ============================================================

def build_report_text(student_state, history, assessment):
    first_names = (student_state or {}).get("first_names") or "élève"
    classe = (student_state or {}).get("class") or "classe"
    restart_count = int((student_state or {}).get("restart_count", 0))

    lines = []

    lines.append("1. Identité")
    lines.append(f"- Prénoms : {first_names}")
    lines.append(f"- Classe : {classe}")
    lines.append(f"- Nombre de recommencements : {restart_count}")
    lines.append("")

    lines.append("2. Dialogue complet de la téléconsultation")
    dialogue = get_consultation_dialogue(history)

    for msg in dialogue:
        speaker = "Élève (médecin)" if msg["role"] == "user" else "M. Dujardin"
        lines.append(f"{speaker} : {msg['content']}")
        lines.append("")

    lines.append("3. Aides utilisées pendant la téléconsultation")
    vocab_used = (student_state or {}).get("vocab_help_used", []) or []
    docs_used = (student_state or {}).get("help_docs_used", []) or []

    if vocab_used:
        lines.append("Aide vocabulaire : " + ", ".join(vocab_used))
    else:
        lines.append("Aide vocabulaire : aucune")

    if docs_used:
        lines.append("Documents de classe consultés :")
        for item in docs_used:
            if isinstance(item, dict):
                lines.append(f"- {item.get('title', item.get('id', 'Document'))}")
            else:
                lines.append(f"- {item}")
    else:
        lines.append("Documents de classe consultés : aucun")

    lines.append("")
    lines.append("4. Ce qu’il faut retenir – correction scientifique")

    for title, explanation in SCIENTIFIC_CORRECTIONS:
        lines.append(f"{title} : {explanation}")
        lines.append("")

    lines.append("5. Bilan pédagogique par compétences")

    for comp in assessment["competences"]:
        level = comp["niveau"]
        lines.append(f"- {comp['nom']} : {LEVEL_LABELS[level]}")
        if "autonomie" in comp:
            lines.append(
                f"  Autonomie observée : niveau {comp['autonomie']} / 4"
            )
        lines.append(f"  Justification : {comp['justification']}")

    lines.append("")
    lines.append("6. Appréciation")
    lines.append(assessment["appreciation"])
    lines.append("")
    lines.append("7. Pour progresser")

    fragile = [
        comp for comp in assessment["competences"]
        if int(comp.get("niveau", 1)) <= 2
    ]

    if fragile:
        lines.append("Après la remédiation en classe, revois en priorité :")
        for comp in fragile:
            lines.append(f"- {comp['nom']}")
    else:
        lines.append(
            "Les connaissances essentielles sont globalement acquises. "
            "Relis la partie « Ce qu’il faut retenir » après la correction en classe."
        )

    if vocab_used:
        lines.append("- Vocabulaire à revoir : " + ", ".join(vocab_used))

    if docs_used:
        lines.append("- Reprendre les documents de classe consultés pendant la téléconsultation.")

    return "\n".join(lines)

