# PDF
# ============================================================

def pdf_safe_text(text):
    replacements = {
        "\u2019": "'",
        "\u2018": "'",
        "\u201c": '"',
        "\u201d": '"',
        "\u2022": "-",
        "\u2013": "-",
        "\u2014": "-",
        "\u00a0": " ",
    }

    for old, new in replacements.items():
        text = text.replace(old, new)

    return text


def build_report_pdf(student_state, history, assessment):
    buffer = BytesIO()

    doc = SimpleDocTemplate(
        buffer,
        pagesize=A4,
        rightMargin=1.4 * cm,
        leftMargin=1.4 * cm,
        topMargin=1.4 * cm,
        bottomMargin=1.4 * cm,
        title="Bilan de téléconsultation SVT - M. Dujardin",
        author="Chatbot pédagogique SVT",
    )

    styles = getSampleStyleSheet()

    title_style = ParagraphStyle(
        "DujardinTitle",
        parent=styles["Title"],
        fontName="Helvetica-Bold",
        fontSize=15,
        leading=18,
        alignment=TA_CENTER,
        spaceAfter=10,
    )

    heading_style = ParagraphStyle(
        "DujardinHeading",
        parent=styles["Heading2"],
        fontName="Helvetica-Bold",
        fontSize=11.5,
        leading=14,
        spaceBefore=8,
        spaceAfter=5,
    )

    body_style = ParagraphStyle(
        "DujardinBody",
        parent=styles["BodyText"],
        fontName="Helvetica",
        fontSize=9,
        leading=12,
        spaceAfter=4,
    )

    small_style = ParagraphStyle(
        "DujardinSmall",
        parent=body_style,
        fontSize=8,
        leading=10,
    )

    story = [
        Paragraph("Bilan de téléconsultation SVT - M. Dujardin", title_style),
    ]

    first_names = (student_state or {}).get("first_names") or "élève"
    classe = (student_state or {}).get("class") or "classe"
    restart_count = int((student_state or {}).get("restart_count", 0))

    story.append(Paragraph("1. Identité", heading_style))
    story.append(
        Paragraph(
            f"<b>Prénoms :</b> {escape(pdf_safe_text(first_names))}",
            body_style,
        )
    )
    story.append(
        Paragraph(
            f"<b>Classe :</b> {escape(pdf_safe_text(classe))}",
            body_style,
        )
    )
    story.append(
        Paragraph(
            f"<b>Nombre de recommencements :</b> {restart_count}",
            body_style,
        )
    )

    story.append(
        Paragraph("2. Dialogue complet de la téléconsultation", heading_style)
    )

    for msg in get_consultation_dialogue(history):
        speaker = "Élève (médecin)" if msg["role"] == "user" else "M. Dujardin"
        content = escape(pdf_safe_text(msg["content"])).replace("\n", "<br/>")

        story.append(
            Paragraph(
                f"<b>{escape(speaker)} :</b> {content}",
                body_style,
            )
        )

    story.append(
        Paragraph("3. Aides utilisées pendant la téléconsultation", heading_style)
    )

    vocab_used = (student_state or {}).get("vocab_help_used", []) or []
    docs_used = (student_state or {}).get("help_docs_used", []) or []

    story.append(
        Paragraph(
            "<b>Aide vocabulaire :</b> "
            + escape(pdf_safe_text(", ".join(vocab_used) if vocab_used else "aucune")),
            body_style,
        )
    )

    if docs_used:
        story.append(Paragraph("<b>Documents de classe consultés :</b>", body_style))
        for item in docs_used:
            title = item.get("title", item.get("id", "Document")) if isinstance(item, dict) else str(item)
            story.append(Paragraph("- " + escape(pdf_safe_text(title)), body_style))
    else:
        story.append(Paragraph("<b>Documents de classe consultés :</b> aucun", body_style))

    story.append(
        Paragraph("4. Ce qu’il faut retenir – correction scientifique", heading_style)
    )

    for title, explanation in SCIENTIFIC_CORRECTIONS:
        story.append(
            Paragraph(
                f"<b>{escape(title)} :</b> {escape(pdf_safe_text(explanation))}",
                body_style,
            )
        )

    story.append(
        Paragraph("5. Bilan pédagogique par compétences", heading_style)
    )

    table_data = [
        [
            Paragraph("<b>Compétence évaluée</b>", small_style),
            Paragraph("<b>Niveau</b>", small_style),
            Paragraph("<b>Justification</b>", small_style),
        ]
    ]

    level_backgrounds = {
        1: colors.HexColor("#FDE2E2"),
        2: colors.HexColor("#FFF0D6"),
        3: colors.HexColor("#E2F5E9"),
        4: colors.HexColor("#E1ECFA"),
    }

    row_levels = []

    for comp in assessment["competences"]:
        level = int(comp["niveau"])
        row_levels.append(level)

        level_text = LEVEL_LABELS[level].split("–", 1)[1].strip()

        table_data.append(
            [
                Paragraph(
                    escape(pdf_safe_text(comp["nom"])),
                    small_style,
                ),
                Paragraph(
                    f"<b>Niveau {level}</b><br/>{escape(level_text)}",
                    small_style,
                ),
                Paragraph(
                    escape(pdf_safe_text(comp["justification"])),
                    small_style,
                ),
            ]
        )

    table = Table(
        table_data,
        colWidths=[6.2 * cm, 3.2 * cm, 8.0 * cm],
        repeatRows=1,
        hAlign="LEFT",
    )

    commands = [
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#EDEDED")),
        ("GRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#999999")),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("LEFTPADDING", (0, 0), (-1, -1), 5),
        ("RIGHTPADDING", (0, 0), (-1, -1), 5),
        ("TOPPADDING", (0, 0), (-1, -1), 4),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
    ]

    for row_index, level in enumerate(row_levels, start=1):
        commands.append(
            (
                "BACKGROUND",
                (1, row_index),
                (1, row_index),
                level_backgrounds[level],
            )
        )

    table.setStyle(TableStyle(commands))
    story.append(table)
    story.append(Spacer(1, 8))

    story.append(Paragraph("<b>Repères des niveaux :</b>", body_style))
    story.append(
        Paragraph(
            "<b>Niveau 1 – Maîtrise insuffisante :</b> bases non assimilées, objectifs non atteints.",
            small_style,
        )
    )
    story.append(
        Paragraph(
            "<b>Niveau 2 – Maîtrise fragile :</b> bases partiellement comprises, besoin d'un étayage important.",
            small_style,
        )
    )
    story.append(
        Paragraph(
            "<b>Niveau 3 – Maîtrise satisfaisante :</b> compétence acquise de manière autonome, niveau attendu.",
            small_style,
        )
    )
    story.append(
        Paragraph(
            "<b>Niveau 4 – Très bonne maîtrise :</b> maîtrise très solide, précise et mobilisée avec aisance.",
            small_style,
        )
    )

    story.append(Paragraph("6. Appréciation", heading_style))
    story.append(
        Paragraph(
            escape(pdf_safe_text(assessment["appreciation"])),
            body_style,
        )
    )

    story.append(Paragraph("7. Pour progresser", heading_style))
    fragile = [
        comp for comp in assessment["competences"]
        if int(comp.get("niveau", 1)) <= 2
    ]

    if fragile:
        story.append(
            Paragraph(
                "Après la remédiation en classe, revois en priorité :",
                body_style,
            )
        )
        for comp in fragile:
            story.append(
                Paragraph(
                    f"- {escape(pdf_safe_text(comp['nom']))}",
                    body_style,
                )
            )
    else:
        story.append(
            Paragraph(
                "Les connaissances essentielles sont globalement acquises. "
                "Relis la partie « Ce qu'il faut retenir » après la correction en classe.",
                body_style,
            )
        )

    if vocab_used:
        story.append(
            Paragraph(
                "<b>Vocabulaire à revoir :</b> "
                + escape(pdf_safe_text(", ".join(vocab_used))),
                body_style,
            )
        )

    if docs_used:
        story.append(
            Paragraph(
                "Reprendre les documents de classe consultés pendant la téléconsultation.",
                body_style,
            )
        )

    doc.build(story)
    buffer.seek(0)
    return buffer.getvalue()

